-- ===============================================================
--  ISPE — TE DHENA TESTIMI
--  350 studente (70 per drejtim) x 4 gjenerata, plane e pagesa te ndryshme
--  Perfshin: studentet + kestet + pagesat (te llogaritura sipas Nenit 6)
--
--  KUJDES: fshin te gjithe studentet ekzistues!
--  Hiqni bllokun "PASTRIMI" nese doni t'i ruani.
--
--  Run: mysql -u root -p ispe_school < seed-testime.sql
-- ===============================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- E nevojshme per MySQL Workbench (safe update mode bllokon DELETE pa WHERE)
SET SQL_SAFE_UPDATES = 0;

-- ---------- PASTRIMI ----------
DELETE FROM payments WHERE id > 0;
DELETE FROM installments WHERE id > 0;
DELETE FROM students WHERE id > 0;
DELETE FROM student_year_history WHERE id > 0;
DELETE FROM promotions WHERE id > 0;
ALTER TABLE students AUTO_INCREMENT = 1;
ALTER TABLE payments AUTO_INCREMENT = 1;
ALTER TABLE installments AUTO_INCREMENT = 1;
-- ------------------------------

SET FOREIGN_KEY_CHECKS = 1;


