-- ---------- PERMBLEDHJE ----------
SELECT c.name AS drejtimi, COUNT(*) AS studente
  FROM students s JOIN categories c ON c.id = s.category_id
 GROUP BY c.name ORDER BY c.name;
SELECT generation, COUNT(*) AS studente FROM students GROUP BY generation ORDER BY generation;
SELECT payment_plan, COUNT(*) AS studente FROM students GROUP BY payment_plan;
SELECT study_year, COUNT(*) AS studente FROM students GROUP BY study_year ORDER BY study_year;

SET SQL_SAFE_UPDATES = 1;
